select id, store_id, product_id, sale_date, units, revenue, max(revenue) over (partition by store_id) as store_id_max_revenue, first_value(units) ignore nulls over (partition by product_id order by revenue, id rows between unbounded preceding and current row) as first_known_units, avg(revenue) over (order by sale_date, id rows between 6 preceding and current row) as revenue_avg_6, sum(revenue) over (partition by store_id) as store_id_sum_revenue, avg(units) over (partition by store_id order by sale_date, id rows between 6 preceding and 1 preceding) as units_avg_6_prior from store_sales
